'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createCodec } = require('../parse');
const { minecraftData } = require('../deps');
const { correctRecipeSerializers } = require('../protocol767');

// Independently specified vanilla wire bytes, not generated by the schema being tested.
const string = value => Buffer.concat([Buffer.from([Buffer.byteLength(value)]), Buffer.from(value)]);
const recipe = (name, serializer, body) => Buffer.concat([
    Buffer.from([0x77, 1]), string(name), Buffer.from([serializer]), body,
]);

test('protocol767 special serializers follow vanilla registration order without obsolete banner-add-pattern', () => {
    const codec = createCodec();
    for (const [id, type] of [[11,'shielddecoration'],[12,'shulkerboxcoloring'],[13,'suspiciousstew'],[14,'repairitem']]) {
        const raw = recipe('minecraft:example', id, Buffer.from([0])); // crafting category
        const decoded = codec.parse('S2C', raw);
        assert.equal(decoded.params.recipes[0].type, `minecraft:crafting_special_${type}`);
        assert.deepEqual(codec.encode('S2C', decoded.name, decoded.params), raw);
    }
    const raw = recipe('minecraft:example', 22, Buffer.from([0]));
    assert.equal(codec.parse('S2C', raw).params.recipes[0].type, 'minecraft:crafting_decorated_pot');
});

test('actual vanilla smelting serializer15 roundtrips result ingredients XP and cooking time', () => {
    const xp = Buffer.alloc(4); xp.writeFloatBE(0.5);
    const raw = recipe('minecraft:test_smelting', 15, Buffer.concat([
        Buffer.from([0,0]), // empty group, miscellaneous category
        Buffer.from([1,1,1,0,0]), // one ingredient option: count1, item1, no components
        Buffer.from([1,2,0,0]), // result count1, item2, no components
        xp, Buffer.from([0xc8,1]), // XP0.5, cookingtime200
    ]));
    const codec = createCodec();
    const decoded = codec.parse('S2C', raw);
    assert.equal(decoded.params.recipes[0].type, 'minecraft:smelting');
    assert.deepEqual(codec.encode('S2C', decoded.name, decoded.params), raw);
});

test('correction is idempotent, limited to767 and never inserts the obsolete serializer', () => {
    const original = minecraftData('1.21.1');
    const data = { version: { version: 767 }, protocol: structuredClone(original.protocol) };
    assert.equal(correctRecipeSerializers(data), false);
    data.version.version = 768;
    assert.equal(correctRecipeSerializers(data), false);
});
